@Bean("batchQueryExecutor")
public ThreadPoolExecutor batchQueryExecutor() {
    // core 8 / max 40 刻意压在连接池 maxActive=50 之下
    return new ThreadPoolExecutor(
            8, 40, 60L, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(200),
            new ThreadFactoryBuilder().setNameFormat("batch-query-%d").build(),
            new ThreadPoolExecutor.CallerRunsPolicy());
}

// 组内并发度另用 Semaphore 控到 4，组间按注册顺序串行
private final Semaphore groupPermit = new Semaphore(4);

private List<Result> runGroups(List<Group> groups) {
    List<Result> all = new ArrayList<>();
    for (Group g : groups) {
        groupPermit.acquire();
        try {
            Future<Result> f = executor.submit(() -> query(g));
            all.add(f.get(30, TimeUnit.SECONDS));   // 每个子任务 30 秒超时
        } finally {
            groupPermit.release();
        }
    }
    return all;
}

@Bean("exportExecutor")
public ThreadPoolExecutor exportExecutor() {
    ThreadPoolExecutor executor = new ThreadPoolExecutor(
            2, 4, 60L, TimeUnit.SECONDS,
            new ArrayBlockingQueue<>(3),            // 10 → 3：导出是重任务，宁可拒不可堆
            new ThreadFactoryBuilder().setNameFormat("export-%d").build(),
            new ThreadPoolExecutor.AbortPolicy());  // 拒绝直接抛，让上层提示繁忙
    return executor;
}

// 提交侧把 RejectedExecutionException 转成业务提示
